// Names a README or GitHub uses for the same thing as a logo above.
const ALIASES: Record<string, string> = { Docker: "Dockerfile", Terraform: "HCL", "Vue.js": "Vue", Vuejs: "Vue", Nodejs: "Node.js", Reactjs: "React", Nextjs: "Next.js", Postgres: "PostgreSQL", Mongo: "MongoDB", Tailwind: "Tailwind CSS", Torch: "PyTorch" }

export function brandLogo(name: string | null | undefined): BrandLogo | null {
  if (!name) return null
  return BRAND_LOGOS[name] ?? BRAND_LOGOS[ALIASES[name] ?? ""] ?? null
}